IG$._source = "dashboard";

IG$.historyManager = function(instance) {
	
	this.addHistory = function (key) {
		unFocus.History.addHistory(key);
	};
	
	this.hasMenu = function() {
		var allhash = unFocus.History.getCurrent();
		if (allhash && allhash != "")
		{
			var basehash = allhash.split('&'),
				p1, p2, i, k, val, s, sa;
			
			for (i=0; i < basehash.length; i++)
			{
				sa = basehash[i];
				s = sa.indexOf("=");
				if (s > 0)
				{
					k = sa.substring(0, s);
					val = sa.substring(s+1);
					
					switch (k)
					{
					case "lang":
						break;
					case "p1":
						p1 = val;
						break;
					case "p2":
						p2 = val;
						break;
					}
				}
			}
			
			if (p1 && p2)
				return true;
		}
		
		return false;
	};
	
	this.historyListener = function() {
		var chash = unFocus.History.getCurrent();
		
		if (chash != null && chash != "" && instance.dlgLogin.logininfo)
		{
			IG$.navigateMenu(instance, chash);
		}
		
		return chash;
	};
	
	unFocus.History.addEventListener('historyChange', this.historyListener);
}

var hist,
	lastHist;

IG$.showLoginProc = function(instance) {
	var lform = $('#loginWindow', instance.target),
		uid = $("#userid");
	lform.hide();
	
	lastHist = null;
	if (!hist)
	{
		hist = new IG$.historyManager(instance);
		hist.historyListener();
	}
}

IG$.navigateMenu = function(instance, allhash)
{
	if (allhash && allhash.length > 0 && lastHist != allhash)
	{
		if(IG$.checkUID(allhash))
		{
			p2 = allhash;
		}
		else
		{
			var basehash = allhash.split('&'),
				p1, p2, i, k, val, s, sa;
			
			for (i=0; i < basehash.length; i++)
			{
				sa = basehash[i];
				s = sa.indexOf("=");
				if (s > 0)
				{
					k = sa.substring(0, s);
					val = sa.substring(s+1);
					
					switch (k)
					{
					case "lang":
						break;
					case "p1":
						p1 = val;
						break;
					case "p2":
						p2 = val;
						break;
					}
				}
			}
		}
		
		if (p2)
		{
			IG$.navigateMenuByUID(instance, p2, p1);
		}
	}
}

