IG$._$$1/*changePassword*/ = function(u1, u2, u3, callback) {
	var panel = null;
		
	var req = new IG$._rpc$();
	req.init(panel, 
		{
			ack: "security",
			payload: {},
			mbody: {}
		}, panel, function(xdoc) {
			var panel = this,
				root = IG$.XGetNode(xdoc, "/smsg"),
				item = IG$.XGetNode(xdoc, "/smsg/item"),
				ltoken;
			
			if (item)
			{
				p1 = IG$.XGetSubNodeText(item, "p1");
				p2 = IG$.XGetSubNodeText(item, "p2");
				
				if (p1 && p2)
				{
					instance.rsaPublicKeyModules = p1;
					instance.rsaPublicKeyExpoenent = p2;
					instance.rsa_kinfo = extitem.p3;
					
					var panel = this,
						opasswd = u1.val(),
						npass1 = u2.val(),
						npass2 = u3.val(),
						enc,
						req;
					
					if (npass1 != npass2)
					{
						IG$.alertmsg(ig$.appname, 'Password is not match with confirm value', null, null, 1, "error");
						return;
					}
					
					enc = IG$.encryptKey(instance, [opasswd, npass1]);
					opasswd = enc[0];
					npass1 = enc[1];
					
					req = new IG$._rpc$();
					req.init(panel, 
						{
							ack: "usercontent",
							payload: {address: "/user"},
							mbody: {option: "changepassword", password: npass1, oldpassword: opasswd}
						}, panel, function(xdoc) {
							callback && callback.execute();
						}, null);
					req.send();
				}
			}
		}, null);
	req.send();
};

