/***********************************************************************
 * AppPageControl: Browser 
 */
 IG$.ctrlBrowserPanel = IG$.extend(IG$.ctrlBase, {
	type: "browser",
	initComponent: function() {
		var me = this;
		
		this.p.push(
			{name: "minheight", type: "property", datatype: "number"},
			{name: "rootpath", type: "property", datatype: "string"},
			{name: "visibleitems", type: "property", datatype: "string"},
			{name: "folder_templates", type: "property", datatype: "string"},
			{name: "templates", type: "property", datatype: "string"},
			{name: "collapsible", type: "property", datatype: "boolean"},
			{name: "foldercollapse", type: "property", datatype: "boolean"},
			{name: "name_exclude", type: "property", datatype: "string"},
			{name: "batchload", type: "property", datatype: "boolean"},
			{name: "itemclick", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},
	invalidate: function () {
		var me = this;
		
		if (me.cmp$)
		{
			me.cmp$.$ex.adjust();
		}
	},
	
	applyApplication: function () {
	},
	
	initDrawing: function () {
		var me = this;
		
		me.cmp$ = new IG$.naviTree({
			instance: me.instance,
			renderTo: me.el$,
			autofit: true,
			header: false,
			move: false
		});
		
		me.tl$.hide();
		me.__pcinit();
		
		me.superclass.prototype.initDrawing.call(me);
	},
	updateProperty: function(k, value) {
		var me = this;
		
		switch(k)
		{
		case "rootpath":
			me.setRootPath();
			break;
		case "minheight":
			me.el$.css({minHeight: value ? "" + value + "px" : "initial"});
			me.invalidate();
			break;
		}
	},
	setRootPath: function() {
		var me = this,
			nodepath = me.property["rootpath"],
			req,
			opt = {},
			mopt = {},
			ack = 5;
		
		if (nodepath)
		{
			opt.uid = nodepath;
			
			if (me.property["batchload"] == true)
			{
				ack = "helpcontent";
				mopt.typelist = "Dashboard;Report";
				mopt.pid = nodepath;
				mopt.option = "search";
			}
			
			req = new IG$._rpc$();
			req.init(me, 
				{
					ack: ack,
					payload: opt,
					mbody: mopt
				}, me, function(jdoc) {
					var tnode = jdoc,
						p,
						i,
						ul;
					
					if (jdoc && (p.type == "Folder" || ack == "helpcontent"))
					{
						ul = $("<ul></ul>").appendTo(me.el$);
						this.addNodes(tnodes, ul);
					}
				}, false);
			req.send();
		}
	}
});

IG$.controls.browser = new IG$.ctrlBrowserPanel({}, null);