// splitter between docking items

IG$.c$DckSplt = function(config) {
	var me = this;
	
	me.docmain = config.docmain;
	me.panel = config.panel;
	me._dir = config.direction;
	
	me._initPos = null;
	me._ghost = null;
	
	me.init();
}

IG$.c$DckSplt.prototype = {
	init: function() {
		var me = this,
			cursor = me._dir == "horizontal" ? "n-resize" : "e-resize";
			
		me.spui = $("<div class='dock-splitter'></div>")
			.attr({unselectable:"on"})
			.css({position: "absolute"})
			.appendTo(me.docmain.box)
			.hide();
			
		me.panel._SP = me.panel._SP || [];
		me.panel._SP.push(me);
		
		if (!ig$._fix_split)
		{
			me.spui.css({cursor: cursor, "user-select": "none", "-webkit-user-select": "none","-khtml-user-select": "none", "-moz-user-select": "none"});
			me.spui.bind("mousedown", function(event) {
				me.startDrag(event);
			});
		}
		else
		{
			me.spui.css({"backgroundColor": "transparent"});
		}
	},
	
	setV: function(v) {
		var me = this;
		
		if (v && !ig$._fix_split)
		{
			me.spui.show();
		}
		else
		{
			me.spui.hide();
		}
	},
	
	startDrag: function(event) {
		var me = this;
		
		if(event.target != me.spui[0])
			return;
			
		event.stopPropagation();
		event.preventDefault();
		
		me._ghost = me._ghost || me.spui.clone(false).appendTo(me.docmain.box);
		me._ghost.css("-webkit-user-select", "none")
		me._poff = me.docmain.box.offset();
		me._initPos = me.spui.position();

		function __doDrag(event) {
			event.stopPropagation();
			event.preventDefault();
			me.doDrag(event);
		}
		
		function __endDrag(event) {
			event.stopPropagation();
			event.preventDefault();
			me.endDrag(event);
			
			$(document).unbind("mousemove", __doDrag).unbind("mouseup", __endDrag);
		}
		
		$(document)
			.bind("mousemove", __doDrag)
			.bind("mouseup", __endDrag);
	},
	
	doDrag: function(event) {
		var me = this,
			incr;
			
		if (!me._ghost) 
			return;
		
		event.stopPropagation();
			
		if (me._dir == "horizontal")
		{
			incr = event.pageY - me._initPos.top - me._poff.top;
			me._ghost.css({top: me._initPos.top + incr});
		}
		else
		{
			incr = event.pageX - me._initPos.left - me._poff.left;
			me._ghost.css({left: me._initPos.left + incr});
		}
	},
	
	endDrag: function(event) {
		event.stopPropagation();
		
		if (!this._ghost)
			return;
		
		var me = this,
			g = me._ghost,
			goff = g.offset(),
			moff = me.docmain.box.offset(),
			p = {
				left: goff.left - moff.left,
				top: goff.top - moff.top
			},
			incr, i, flsize = 0, fisize = 0,
			arr,
			base1 = (me._dir == "horizontal" ? "top" : "left"),
			base2 = (me._dir == "horizontal" ? "height" : "width"),
			base3 = (me._dir == "horizontal" ? "h" : "w"),
			pnl,
			qindex = -1,
			pbefore,
			panel = me.panel,
			_pi = 0;
			_pitem = panel.parent,
			mval = 40;
		
		incr = p[base1] - me._initPos[base1];
		
		for (i=0; i < _pitem.children.length; i++)
		{
			if (_pitem.children[i] == panel)
			{
				_pi = i;
				break;
			}
		}
		
		pbefore = _pitem.children[_pi-1];
		
		if (panel.lt.pos[base3] - incr < mval)
		{
			incr = panel.lt.ubody[base3] - mval;
		}
		
		if (pbefore.lt.pos[base2] + incr < mval)
		{
			incr = mval - pbefore.lt.pos[base3];
		}
		
		pbefore.lt.pos[base3] = pbefore.lt.pos[base3] + incr;
		panel.lt.pos[base3] = panel.lt.pos[base3] - incr;
		
		pbefore.lt.ubody.lt[base3] = pbefore.lt.pos[base3];
		panel.lt.ubody.lt[base3] = panel.lt.pos[base3];
		
		me._ghost.remove(); 
		me._ghost = null;	
		
		me.docmain.resizeContainer.call(me.docmain, [pbefore, panel]);
		
		me.docmain.updateDisplay.call(me.docmain, true);
	},
	
	remove: function() {
		var me = this;
		me.spui.remove();
	},
	
	validate: function() {
		var me = this,
			_dir = me._dir,
			gap = 1, m = 1,
			px=0, py=0, pw=0, ph=0,
			mx, my, mw, mh,
			i,
			panel = me.panel,
			pos,
			ubody = panel.lt.ubody;
		
		if (panel)
		{
			pos = panel.lt.pos;
			
			switch (me._dir)
			{
			case "vertical":
				px = pos.x;
				py = pos.y + pos.h * 0.1;
				pw = gap * 2;
				ph = pos.h * 0.8;
				break;
			case "horizontal":
				px = pos.x + pos.w * 0.1;
				py = pos.y;
				pw = pos.w * 0.8;
				ph = gap * 2;
				break;
			}
			
			me.spui.removeClass("split-no-border");
			
			if (ubody && ubody.panel_css)
			{
				if (ubody.panel_css.indexOf("no_border") > -1)
				{
					me.spui.addClass("split-no-border");
				}
			}
				
			me.spui.css({top: py, left: px, width: pw, height: ph});
		}
	}
}