IG$.dlgsqlview = $s.extend($s.window, {
	xtype: "window",
	
	modal: true,
	region:'center',
	
	layout: 'fit',
	
	closable: false,
	resizable:false,
	
	width: 500,
	height: 400,
	
	defaults:{
		padding: ig$.padding
	},
	
	_confirm: function() {
		var me = this,
			sql_name_sel = me.down("[name=sql_name_sel]"),
			content = {};
		
		if (me.getAllValues(content))
			return;
			
		me._confirm_csql();
		
		if (me._$eopt)
		{
			IG$.alertmsg(ig$.appname, IRm$.r1("M_CONFIRM_CLOSE"));
			return;
		}
		
		if (me.sheetoption)
		{
			if (!me.sheetoption.model.sql_id)
			{
				me.sheetoption.model.sql_id = sql_name_sel.getValue();
			}
			else if (me.sheetoption.model.sql_id != sql_name_sel.getValue())
			{
				IG$.confirmMessages(ig$.appname, IRm$.r1("L_C_SWAPSQL"), function(e) {
					if (e == "yes")
					{
						me.sheetoption.model.sql_id = sql_name_sel.getValue();
						me.callback && me.callback.execute(me.inlineview_sql_objects);
						me.close();
					}
				});
				
				return;
			}
		}
		
		me.callback && me.callback.execute(me.inlineview_sql_objects);
		me.close();
	},
	
	validateQuery: function() {
		var me = this,
			req = new IG$._rpc$(),
			content = {
				inline_views: []
			},
			scontent = {};
			
		if (me.getAllValues(scontent))
			return;
		
		content.inline_views.push({
			dbpool: me.reportoption._mc.sql_datasource ? me.reportoption._mc.sql_datasource.uid : null,
			sql: IG$._encodeVal(scontent.sql)
		});
		
		req.init(me, 
			{
				ack: "olapservice",
				payload: {uid: me.sheetoption.uid, option: "sqlcubemeta"},
				mbody: content,
				meta_type: "inlineviews"
			}, me, function(jdoc) {
				var mjdoc;
				
				if (jdoc && jdoc.length)
				{
					mjdoc = jdoc[0];
					IG$.alertmsg(ig$.appname, IRm$.r1("M_VALIDATED") + "(" + (mjdoc.columns ? mjdoc.columns.length : "0") + " columns)", null, null, 0, "success");
				}
			}, null);
		req.send();
	},
	
	requestSQLResult: function() {
		var me = this;
		if (me.meta_type == "sql_report" && me.editmode)
		{
			var inlineview_sql_objects = [],
				sql_name_sel = me.down("[name=sql_name_sel]"),
				mc_sql;
			
			me.inlineview_sql_objects = inlineview_sql_objects;
			mc_sql = me.reportoption._mc.inlineview_sql_objects = me.reportoption._mc.inlineview_sql_objects || [];
			
			$.each(mc_sql, function(i, sql) {
				inlineview_sql_objects.push({
					sql_id: sql.sql_id,
					name: sql.name,
					description: sql.description,
					sql_inlineview: sql.sql_inlineview
				});
			});
			
			if (mc_sql.length == 0)
			{
				inlineview_sql_objects.push({
					sql_id: "sql_1",
					name: "SQL 1",
					description: null,
					sql_inlineview: null
				});
			}
			
			me._refresh_sql();
			
			if (me.sheetoption && me.sheetoption.model.sql_id)
			{
				sql_name_sel.setValue(me.sheetoption.model.sql_id);
			}
			else
			{
				sql_name_sel.setValue(inlineview_sql_objects[0].sql_id);
			}
		}
		else
		{
			if (me.sheetoption != null && me.reportoption != null)
			{
				var pivotxml = me.reportoption.getCurrentPivot(),
					req = new IG$._rpc$();
					
				req.init(me, 
					{
						ack: "olapservice",
						payload: {uid: me.uid, option: "sql", active: "" + me.activeSheet},
						mbody: pivotxml,
						meta_type: me.meta_type || "report"
					}, me, me.rs_requestSQLResult, null);
				req.send();
			}
			else if (me.sql)
			{
				me.rs_requestSQLResult({
					sql: me.sql
				});
			}
		}
	},
	
	_refresh_sql: function() {
		var me = this,
			sql_name_sel = me.down("[name=sql_name_sel]"),
			mc_sql = me.inlineview_sql_objects;
			
		sql_name_sel.store.loadData(mc_sql);
	},
	
	rs_requestSQLResult: function(jdoc) {
		var me = this,
			sql,
			html = me.down('[name=sql]');
		
		html.setValue(jdoc ? jdoc.sql : null);
	},
	
	_update_sql: function() {
		var me = this,
			sql_name_sel = me.down("[name=sql_name_sel]"),
			sql_id = me.down("[name=sql_id]"),
			html = me.down("[name=sql]"),
			rpt_sql,
			inlineview_sql_objects = me.inlineview_sql_objects,
			sval = sql_name_sel.getValue(),
			i;
		
		me._confirm_csql();
		
		for (i=0; i < inlineview_sql_objects.length; i++)
		{
			if (inlineview_sql_objects[i].sql_id == sval)
			{
				rpt_sql = inlineview_sql_objects[i];
				break;
			}
		}
		
		me.$rpt_sql = rpt_sql;
		sql_id.setValue(rpt_sql ? rpt_sql.sql_id : null);
		html.setValue(rpt_sql ? IG$._decodeVal(rpt_sql.sql_inlineview) : null);
		
		setTimeout(function() {
			html.focus();
		}, 100);
	},
	
	_get_max: function() {
		var me = this,
			inlineview_sql_objects = me.inlineview_sql_objects,
			i,
			max_id = 1,
			sid;
		
		for (i=0; i < inlineview_sql_objects.length; i++)
		{
			sid = inlineview_sql_objects[i].sql_id;
			
			if (sid.indexOf("_") > 0)
			{
				sid = Number(sid.substring(sid.indexOf("_") + 1));
				max_id = Math.max(sid + 1, max_id);
			}
		}
		
		return max_id;
	},
	
	_confirm_csql: function() {
		var me = this,
			html = me.down('[name=sql]');
		
		if (me.$rpt_sql)
		{
			me.$rpt_sql.sql_inlineview = IG$._encodeVal(html.getValue());
		}
	},
	
	_confirm_editname: function() {
		var me = this,
			frm_sql_sel = me.down("[name=frm_sql_sel]"),
			frm_sql_new = me.down("[name=frm_sql_new]"),
			sql_name = me.down("[name=sql_name]"),
			html = me.down("[name=sql]"),
			sql_name_sel = me.down("[name=sql_name_sel]"),
			inlineview_sql_objects = me.inlineview_sql_objects;
		
		sql_name.clearInvalid();
		html.clearInvalid();
		
		if (!sql_name.getValue())
		{
			sql_name.setInvalid("Required!");
			return;
		}
		
		if (!html.getValue())
		{
			html.setInvalid("Required!");
		}
		
		if (me._$eopt == "edit")
		{
			me.$rpt_sql.name = sql_name.getValue();
		}
		else
		{
			me.$rpt_sql = {
				sql_id: "sql_" + me._get_max(),
				name: sql_name.getValue(),
				sql_inlineview: IG$._encodeVal(html.getValue())
			};
			
			inlineview_sql_objects.push(me.$rpt_sql);
		}
		
		me._$eopt = null;
		me._refresh_sql();
		sql_name_sel.setValue(me.$rpt_sql.sql_id);
		
		frm_sql_sel.show();
		frm_sql_new.hide();
	},

	_edit: function() {
		var me = this;
		me.close();
		me.edit_callback && me.edit_callback.execute();
	},
	
	initComponent : function() {
		var me = this;
		
		$s.apply(me, {
			title: me.title || IRm$.r1('L_VIEW_SQL'),
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					items: [
						{
							xtype: "container",
							name: "frm_sql_sel",
							hidden: me.meta_type == "sql_report" && me.editmode ? false : true, // && ig$.$l_ < 4 
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "combobox",
									fieldLabel: IRm$.r1("B_NAME"),
									name: "sql_name_sel",
									labelAlign: "left",
									valueField: "sql_id",
									displayField: "name",
									value: "",
									editable: false,
									store: {
										xtype: "store",
										fields: [
										]
									},
									listeners: {
										change: function(tobj) {
											var me = this;
											
											this._update_sql();
										},
										scope: this
									}
								},
								{
									xtype: "button",
									name: "btn_edit",
									text: IRm$.r1("B_EDIT"),
									handler: function() {
										var me = this,
											frm_sql_sel = me.down("[name=frm_sql_sel]"),
											frm_sql_new = me.down("[name=frm_sql_new]"),
											sql_name = me.down("[name=sql_name]");
										
										if (!me.$rpt_sql)
											return;
										
										me._$eopt = "edit";
										sql_name.setValue(me.$rpt_sql ? me.$rpt_sql.name : null);
										
										frm_sql_sel.hide();
										frm_sql_new.show();
										
										setTimeout(function() {
											sql_name.focus();
										}, 100);
									},
									scope: this
								},
								{
									xtype: "button",
									text: IRm$.r1("B_ADD"),
									handler: function() {
										var me = this,
											frm_sql_sel = me.down("[name=frm_sql_sel]"),
											frm_sql_new = me.down("[name=frm_sql_new]"),
											sql_name = me.down("[name=sql_name]"),
											html = me.down("[name=sql]");
										
										me._confirm_csql();
										
										me._$eopt = "new";
										sql_name.setValue("");
										html.setValue("");
										
										me.$rpt_sql = null;
										
										frm_sql_sel.hide();
										frm_sql_new.show();
										
										setTimeout(function() {
											sql_name.focus();
										}, 100);
									},
									scope: this
								}
							]
						},
						{
							xtype: "container",
							name: "frm_sql_new",
							hidden: true,
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("B_NAME"),
									name: "sql_name",
									enableKeyEvents: true,
									listeners: {
										keyup: function(tobj, e, eopts) {
											if (e.keyCode == 13)
											{
												this._confirm_editname();
											}
										},
										scope: this
									}
								},
								{
									xtype: "button",
									text: IRm$.r1("B_CONFIRM"),
									bodyCls: "ig-btn-confirm",
									handler: function() {
										var me = this;
										me._confirm_editname();
									},
									scope: this
								},
								{
									xtype: "button",
									text: IRm$.r1("B_CANCEL"),
									handler: function() {
										var me = this,
											frm_sql_sel = me.down("[name=frm_sql_sel]"),
											frm_sql_new = me.down("[name=frm_sql_new]");
										
										me._$eopt = null;
										
										me._update_sql();
										
										frm_sql_sel.show();
										frm_sql_new.hide();
									},
									scope: this
								}
							]
						},
						{
							xtype: "textfield",
							fieldLabel: IRm$.r1("L_SQL_ID"),
							name: "sql_id",
							hidden: true, // me.meta_type == "sql_report" ? false : true,
							readOnly: true
						},
						{
							xtype: "textarea",
							name: 'sql',
							required: true,
							readOnly: me.meta_type == "sql_report" && me.editmode ? false : true
						}
					]
				}
			],
			buttons: [
				{
					text: IRm$.r1("B_EDIT"),
					hidden: me.meta_type == "sql_report" && !me.editmode ? false : true,
					handler: function() {
						this._edit();
					},
					scope: this
				},
				{
					text: IRm$.r1("B_VALIDATE"),
					hidden: me.meta_type == "sql_report" && me.editmode ? false : true,
					handler: function() {
						this.validateQuery();
					},
					scope: this
				},
				{
					xtype: "button",
					text: IRm$.r1("B_REMOVE"),
					hidden: me.meta_type == "sql_report" && me.editmode ? false : true, // ig$.$l_ < 5 ? 
					handler: function() {
						var me = this,
							inlineview_sql_objects = me.inlineview_sql_objects,
							sql_name_sel = me.down("[name=sql_name_sel]");
						
						if (inlineview_sql_objects.length < 2)
						{
							IG$.alertmsg(ig$.appname, IRm$.r1("L_C_SQL_NON"), null, null, 0, "success");
							return;
						}
						
						IG$.confirmMessages(ig$.appname, IRm$.r1("L_C_REMSQL"), function(e) {
							if (e == "yes")
							{
								var i;
								
								for (i=0; i < inlineview_sql_objects.length; i++)
								{
									if (inlineview_sql_objects[i].sql_id == me.$rpt_sql.sql_id)
									{
										inlineview_sql_objects.splice(i, 1);
										break;
									}
								}
								
								me._refresh_sql();
								sql_name_sel.setValue(inlineview_sql_objects[0].sql_id);
							}
						});
					},
					scope: this
				},
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					hidden: me.meta_type == "sql_report" && me.editmode ? false : true,
					handler: function() {
						this._confirm();
					},
					scope: this
				},
				{
					text: IRm$.r1('B_CLOSE'),
					handler: function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					this.requestSQLResult();
				}
			}
		});
		
		IG$.dlgsqlview.superclass.initComponent.apply(this, arguments);
	}
});
