/**
 * @module widget/rfNavi
 * @desc Report Navi Control
 *
 */
IG$.rfNavi = function (instance, container, sop, rop, report) {
	var me = this;
	
	me.instance = instance;
	me.container = container;
	me.sheetoption = sop;
	me.reportoption = rop;
	me.rpt = report;
	
	me.updateValues = true;
	
	me.$init();
};

IG$.rfNavi.prototype = {
	$init: function() {
		var me = this,
			values = {},
			rop = me.reportoption,
			browser;
		
		me.contentarea = $("<div></div>").appendTo(me.container);
		
		this.browser = browser = new IG$.naviTree({
			instance: me.instance,
			renderTo: me.contentarea[0],
			showtoolbar: false,
			cubebrowse: true,
			showcheckselect: false,
			collapsible: false,
			floatable: false,
			floating: false,
			flex: 5,
			layout: "fit",
			enabledrag: true,
			checkStateChanged: me.checkStateChangedHandler
		});
		
		values.type = (me.reportoption.reportmode == "rolap") ? "Cube" : "Metric";
		values.name = values.type;
		values.nodepath = values.type;
		values.uid = me.reportoption.cubeuid || null;
			
		values.leaf = false;
		
		browser.store.setRootNode(values);
	},
	
	removeObj: function() {
		var me = this;
		me.browser = null;
	},
	
	validateItems: function() {
		
	},
	
	setSize: function(w, h) {
		var me = this,
			c = me.contentarea;
		
		IG$.j$ext._w(c, w);
		IG$.j$ext._h(c, h);
		me.browser.setWidth(w);
		me.browser.setHeight(h);
	},
	
	updateFilterContent: function(finfo) {
	}
};

