/**
 * checkbuttons control
 */
IG$._FC_checkbuttons = $s.extend(IG$._baseFC, {
	objtype: "checkbuttons",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			ui = $("<table class='idv-checkbuttons'><tr><td><ul></ul></td></tr></table>")
				.appendTo(container),
			td = $("td", ui);

		if (me.md)
		{
			td.empty();
			td.append($("<md-chip-set></md-chip-set>"));
		}
			
		td.bind("checkboxchanged", function(ev, dt) {
			if (me.md)
			{
				if (dt && fitem._c_a1 && fitem._c_a1[0].selected)
				{
					fitem._c_a1[0].selected = false;
				}
			}
			else if (dt && fitem._c_a1 && $("input[type='checkbox']", fitem._c_a1).is(':checked') && !$("input[type='checkbox']", dt.u2).is(':checked'))
			{
				$("input[type='checkbox']", fitem._c_a1).prop("checked", false);
			}
			
			me.trigger("change_val", fitem.updateValues == true);
		});
		return ui;
	},
	setValue: function(value, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			i, sctrl1;
			
		if (fitem.data)
		{
			for (i=0; i < fitem.data.length; i++)
			{
				sctrl1 = me.md ? fitem.data[i].u2[0] : $("input[type='checkbox']", fitem.data[i].u2);
				
				if (cmap[fitem.data[i].code])
				{
					if (me.md)
						sctrl1.selected = true;
					else
						sctrl1.attr("checked", "checked");
				}
				else
				{
					if (me.md)
						sctrl1.selected = false;
					else
						sctrl1.removeAttr("checked");
				}
			}
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			j;
			
		if (fitem.data)
		{
			for (j=0; j < fitem.data.length; j++)
			{
				if (me.md)
				{
					if (fitem.data[j].u2 && fitem.data[j].u2[0].selected)
					{
						value.push({code: fitem.data[j].code, value: fitem.data[j].value});
					}
				}
				else if (fitem.data[j].u2 && $("input[type='checkbox']", fitem.data[j].u2).is(':checked'))
				{
					value.push({code: fitem.data[j].code, value: fitem.data[j].value});
				}
			}
		}
	},
	loadData: function(data) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			ui = me.ui,
			td,
			inp,
			box,
			aname,
			dval;

		if (me.md)
		{
			td = $("md-chip-set", ui);
		}
		else
		{
			td = $("ul", ui);
		}
			
		td.empty();
		
		dval = me.getDefaultValue(fitem, 0);
		
		if (fmodel.showallvalue)
		{
			aname = fmodel.aname || IRm$.r1("L_SELECT_VALUE");

			function sa_click_hanlder() {
				td.trigger("checkbox_sel_all");
				
				fitem.___prv_event = 1;
				
				var s = 0;
				
				if (me.md)
				{
					s = inp[0].selected;
				}
				else if ($("input[type='checkbox']", inp).is(':checked'))
				{
					s = 1;
				}
				
				$.each(data, function(i, dt) {
					if (dt.u2)
					{
						var dobj = me.md ? dt.u2[0] : $("input[type='checkbox']", dt.u2);
						if (me.md)
						{
							dobj.selected = s ? true : false;
						}
						else
						{
							dobj.prop("checked", s ? true : false);
						}
					}
				});
				
				fitem.___prv_event = 0;
				
				td.trigger("checkboxchanged", null);
			}

			if (me.md)
			{
				box = td;
				inp = $("<md-filter-chip elevated='true'></md-filter-chip>");
				box.append(inp);
				inp[0].update();
				// inp.labels = $("<label><span>" + (aname) + "</span></label>").appendTo(box)[0];
				inp[0].label = aname;

				if (dval == "ALL")
				{
					inp[0].selected = true;
				}

				inp[0].addEventListener("click", sa_click_hanlder);
			}
			else
			{
				box = $("<li class='igc-chk-sel-all'></li>").appendTo(td);

				inp = $("<label><input type='checkbox' value=''/><span>" + (aname) + "</span></label>").appendTo(box);
				
				if (dval == "ALL")
				{
					$("input[type='checkbox']", inp).prop("checked", true);
				}

				inp.bind("click", sa_click_hanlder);
			}

			fitem._c_a1 = inp;
		}
		
		$.each(data, function(i, dt) {
			var box;
			var inp;

			if (me.md)
			{
				box = td;
				inp = $("<md-filter-chip></md-filter-chip>");
				box.append(inp);
				inp[0].update();
				// inp.labels = $("<label><span>" + (dt.disp || dt.code) + "</span></label>").appendTo(box)[0];;
				inp[0].label = (dt.disp || dt.code);
			}
			else
			{
				box = $("<li></li>").appendTo(td);
				inp = $("<label><input type='checkbox' value='" + dt.code + "'/><span>" + (dt.disp || dt.code) + "</span></label>").appendTo(box);
			}
			
			var inp_b = me.md ? inp[0] : $("input[type='checkbox']", inp);
				
			dt.u2 = inp;
			dt.u2b = inp_b;
			
			if (dt.code == dval || dt.selected || dval == "ALL")
			{
				if (me.md)
				{
					inp_b.selected = true;
				}
				else
				{
					inp_b.prop("checked", true);
				}
			}
			
			if (me.md)
			{
				inp_b.addEventListener("click", function() {
					if (!fitem.___prv_event)
					{
						td.trigger("checkboxchanged", dt);
					}
				});
			}
			else
			{
				inp_b.bind("change", function() {
					if (!fitem.___prv_event)
					{
						td.trigger("checkboxchanged", dt);
					}
				});
			}
		});
		
		td.trigger("checkboxchanged", null);
	},
	clear: function() {
		var me = this,
			fitem = me.fitem,
			fd = fitem.data,
			i;
			
		if (fd && fd.length)
		{
			for (i=0; i < fd.length; i++)
			{
				if (me.md)
				{
					if (fd[i].u2)
					{
						fd[i].u2.selected = false;
					}
				}
				else
				{
					fd[i].u2 && $("input[type='checkbox']", fd[i].u2).prop("checked", false);
				}
			}
		}
		me.trigger("change_val");
	}
});

IG$.$FCinst["checkbuttons"] = new IG$._FC_checkbuttons();