/**
 * slider control
 */
IG$._FC_slider = $s.extend(IG$._baseFC, {
	objtype: "slider",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			ui = $("<div class='idv-sel-combo'></div>").appendTo(container),
			fid = me._get_id(),
			s1a, s1b, s1c, ui,
			m1;
			
		s1a = fmodel.s1a ? Number(fmodel.s1a) : 0;
		s1b = fmodel.s1b ? Number(fmodel.s1b) : 100;
		s1c = fmodel.s1c ? Number(fmodel.s1c) : 1;

		if (me.md)
		{
			me.lbl$ = $("<label class='form-label' for='" + fid + "'></label>").appendTo(ui);
			m1 = $("<md-slider id='" + fid + "' style='flex:1' range='true' labeled='true'></md-slider>").appendTo(ui);
			m1[0].labels = me.lbl$;
			me.mp$ = m1[0];
			me.updateSlideValue();

			me.mp$.addEventListener("change", function(e) {
				me.slideValueHandler();
				me.updateSlideValue();
				me.trigger("change_val");
			});
		}
		else
		{
			m1 = $("<div class='igc-slider'></div>").appendTo(ui).slider({
				orientation: "horizontal",
				range: true,
				min: s1a,
				max: s1b,
				values: [s1a, s1b],
				step: s1c,
				create: function(event, ctrl) {
					me.updateSlideValue(this);
				},
				
				slide: function(event, ctrl) {
					var loffset = $(this).offset(),
						offset = $(ctrl.handle).offset(),
						l = offset.left - loffset.left;
					
					me.slideValueHandler(this, ctrl, l);
				},
				
				change: function(event, ctrl) {
					if (fitem.updateValues)
						return;
					me.updateSlideValue(this);
					me.trigger("change_val");
				},
				
				start: function(event, ctrl) {
					$("<div class='guide'></div>")
						.appendTo(this);
				},
				
				stop: function(event, ctrl) {
					var guide = $(this).children(".guide");
					
					if (guide)
					{
						guide.remove();
					}
				}
			});
		}

		me.m1 = m1;
		
		return ui;
	},
	
	loadData: function(data) {
		var me = this,
			fmodel = me.fmodel,
			m1 = me.m1,
			i, max, min, allnumeric = true,
			step, tvalue, s1a, s1b, s1c;
			
		if (data && data.length)
		{
			min = parseFloat(data[0].code);
			max = min;
			for (i=0; i < data.length; i++)
			{
				tvalue = parseFloat(data[i].code);
				if (isNaN(tvalue) == false)
				{
					min = Math.min(tvalue, min);
					max = Math.max(tvalue, max);
				}
				else
				{
					allnumeric = false;
					break;
				}
			}
			
			fmodel.allnumeric = allnumeric;
			
			if (allnumeric)
			{
				step = (max-min) / Math.max(data.length, 20);
				s1a = fmodel.s1a ? Number(fmodel.s1a) : min;
				s1b = fmodel.s1b ? Number(fmodel.s1b) : max;
				s1c = fmodel.s1c ? Number(fmodel.s1c) : step;
			}
			else
			{
				s1a = fmodel.s1a ? Number(fmodel.s1a) : 0;
				s1b = fmodel.s1b ? Number(fmodel.s1b) : data.length;
				s1c = fmodel.s1c ? Number(fmodel.s1c) : 1;
			}
			
			if (me.md)
			{
				var mp$ = me.mp$;
				mp$.min = s1a;
				mp$.max = s1b;
				mp$.step = s1c;
				mp$.valueStart = s1a;
				mp$.valueEnd = s1b;
			}
			else
			{
				m1.slider("option", "min", s1a);
				m1.slider("option", "max", s1b);
				m1.slider("option", "step", s1c);
				m1.slider("values", 0, s1a);
				m1.slider("values", 1, s1b);
			}
			
			me.updateSlideValue(m1);
		}
	},
	updateValue: function(value) {
		var me = this,
			m1 = me.m1,
			mp$ = me.mp$,
			fitem = me.fitem,
			fmodel = me.fmodel,
			i0 = me.md ? mp$.valueStart : m1.slider("values", 0),
			i1 = me.md ? mp$.valueEnd : m1.slider("values", 1),
			min = me.md ? mp$.min : m1.slider("option", "min"),
			max = me.md ? mp$.max : m1.slider("option", "max"),
			j;
		
		if (fmodel.allnumeric == false)
		{
			if (i0 || i1 < fitem.data.length)
			{
				for (j=i0; j < i1; j++)
				{
					value.push({code: fitem.data[j].code, value: fitem.data[j].disp, operator: "EQ"});
				}
			}
		}
		else if (min < i0 || max > i1)
		{
			value.push({code: "" + i0, value: "" + i0, operator: "GTE"});
			value.push({code: "" + i1, value: "" + i1, operator: "LTE"});
		}
	},
	setValue: function(value, cmap, svalues) {
		var me = this,
			m1 = me.m1,
			mp$ = me.mp$;

		if (me.md)
		{
			mp$.valueStart = value[0] ? Number(value[0]) : 0;
			mp$.valueEnd = value[1] ? Number(value[1]) : 1;
		}
		else
		{
			m1.slider("values", 0, value[0] ? Number(value[0]) : 0);
			m1.slider("values", 1, value[1] ? Number(value[1]) : 1);
		}
	},
	clear: function() {
		var me = this,
			m1 = me.m1,
			mp$ = me.mp$,
			min = me.md ? mp$.min : m1.slider("option", "min"),
			max = me.md ? mp$.max : m1.slider("option", "max");
		
		if (me.md)
		{
			mp$.valueStart = min;
			mp$.valueEnd = max;
		}
		else
		{
			m1.slider("values", 0, min);
			m1.slider("values", 1, max);
		}
	},
	updateSlideValue: function(slider) {
		var i, 
			me = this,
			slide = $(slider),
			mp$ = me.mp$,
			filteritem = me.fitem,
			handles = me.md ? [1, 1] : slide.children("a"),
			handle,
			value;
	
		if (handles && handles.length == 2)
		{
			for (i=0; i < handles.length; i++)
			{
				if (me.md)
				{
					value = i == 0 ? mp$.valueStart : mp$.valueEnd;
				}
				else
				{
					value = slide.slider("values", i);
				}
				
				if (filteritem && filteritem.data && filteritem.allnumeric == false)
				{
					if (filteritem.data.length > value)
					{
						value = "" + filteritem.data[value].code;
					}
					else
					{
						value = "";
					}
				}
				else
				{
					value = "" + value;
				}
				
				if (me.md)
				{
					if (i == 0)
					{
						mp$.valueLabelStart = value;
					}
					else
					{
						mp$.valueLabelEnd = value;
					}
				}
				else
				{
					handle = $(handles[i]);
					
					handle.tooltip({
						track: true,
						delay: 0,
						fade: 250,
						showURL: false
					});
					
					handle[0].tooltipText = value;
				}
			}
		}
	},
	slideValueHandler: function(slider, ctrl, left) {
		var i, 
			me = this,
			slide = slider ? $(slider) : null,
			mp$ = me.mp$,
			filteritem = me.fitem,
			handles = me.md ? [1, 1] : slide.children("a"),
			// handle,
			value, 
			guide;
	
		if (handles && handles.length == 2)
		{
			for (i=0; i < handles.length; i++)
			{
				if (me.md || (ctrl && ctrl.handle == handles[i]))
				{
					if (me.md)
					{
						value = i == 0 ? mp$.valueStart : mp$.valueEnd;
					}
					else
					{
						value = slide.slider("values", i);
					}
					
					if (filteritem && filteritem.data && filteritem.allnumeric == false)
					{
						if (filteritem.data.length > value)
						{
							value = "" + filteritem.data[value].code;
						}
						else
						{
							value = "";
						}
					}
					else
					{
						value = "" + value;
					}
					
					if (me.md)
					{
						if (i == 0)
						{
							mp$.valueLabelStart = value;
						}
						else
						{
							mp$.valueLabelEnd = value;
						}
					}
					else
					{
						guide = slide.children(".guide");
						guide.css({left: left}).html(value);
					}
				}
			}
		}
	}
});

IG$.$FCinst["slider"] = new IG$._FC_slider();