IG$.workspace_switcher = $s.extend($s.window, {
	modal: true,
	region:'center',
	
	layout: "fit",
	
	closable: false,
	resizable:false,
	
	width: 380,
	autoHeight: true,
	
	loadMTS: function() {
		var panel = this,
			mkw = panel.down("[name=mkw]"),
			req = new IG$._rpc$();
		req.init(panel, 
			{
				ack: "usercontent",
				payload: {address: "/tenants", action: "get", keyword: mkw.getValue()},
				mbody: {option: "select"}
			}, panel, function(jdoc) {
				var i,
					cnodes,
					mts,
					mtslist = [];
				
				if (jdoc)
				{
					for (i=0; i < jdoc.length; i++)
					{
						mts = jdoc[i];
//						switch (mts.pstatus)
//						{
//						case "A":
//							mts.pstatname = "App";
//							break;
//						case "1":
//							mts.pstatname = "Active";
//							break;
//						default:
//							mts.pstatname = "Disabled";
//							break;
//						}
						(mts.status == "1" || mts.status == "A") && mtslist.push(mts);
					}
				}
				
				this.down("[name=mtsgrd]").store.loadData(mtslist);
			}, false);
		req.send();
	},
	
	confirm: function() {
		var panel = this,
			mtsgrd = panel.down("[name=mtsgrd]"),
			sel = mtsgrd.getSelectionModel().selected;
		
		if (sel && sel.length)
		{
			IG$.confirmMessages(IRm$.r1("B_CONFIRM"), IRm$.r1("L_SWA_CFM"), function(dlg) {
				if (dlg == "yes")
				{
					var rec = sel.items[0],
						nmts = rec.get("uid"),
						nmtsname = rec.get("name"),
						curl = document.location.href;
					
					if (curl.indexOf("?") > -1)
					{
						curl = curl.substring(0, curl.indexOf("?"));
					}	
					
					// ?lang=ko_KR&mts=0122483f-0155fb46&_d=308
					curl = curl + "?lang=" + (window.useLocale || "en_US") + "&mts=" + nmts;
					
					document.location.href = curl;
				}
			}, panel, panel);
		}
		else
		{
			IG$.alertmsg(ig$.appname, IRm$.r1("E_SWA_CFM"), null, null, 0, "error");
		}
	},
	
	initComponent: function() {
		
		$s.apply(this, {
			title: IRm$.r1("L_SW_APP"),
			items: [
				{
					xtype: "panel",
					bodyPadding: ig$.padding,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							xtype: "container",
							layout: "hbox",
							items: [
								{
									xtype: "textfield",
									labelAlign: "right",
									fieldLabel: IRm$.r1("B_SEARCH"),
									name: "mkw",
									labelWidth: 60,
									width: 200,
									emptyText: IRm$.r1("L_SEARCH_KWD"),
									enableKeyEvents: true,
									listeners: {
										keyup: function(tobj, e, eopts) {
											if (e.keyCode == 13)
											{
												this.loadMTS();
											}
										},
										scope: this
									}
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									handler: function() {
										this.loadMTS();
									},
									scope: this
								}
							]
						},
						{
							xtype: "gridpanel",
							hideHeaders: true,
							name: "mtsgrd",
							height: 150,
							store: {
								xtype: "store",
								fields: [
									"name", "uid"
								]
							},
							selType: "checkboxmodel",
							selModel: {
								checkSelector: ".x-grid-cell",
								mode: "SINGLE"
							},
							columns: [
								{
									text: IRm$.r1("B_NAME"),
									dataIndex: "name",
									flex: 1
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this.confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CANCEL'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			]
		});
		IG$.workspace_switcher.superclass.initComponent.apply(this, arguments);
	}

});

IG$.passwordMgr = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	
	layout: {
		type: 'vbox',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	
	width: 380,
	autoHeight: true,
	
	parentnodepath: null,
	itemtype: null,
	parentuid: null,
	
	callback: null,
	
	processChangePasswd: function(is_main){
		var me = this,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "security",
				payload: {},
				mbody: {}
			}, me, me.rs_getSecureKey, null, [is_main]);
		req.send();
	},
	
	rs_getSecureKey: function(jdoc, is_main) {
		var me = this,
			instance = me.instance,
			ltoken;
		
		if (jdoc)
		{
			p1 = jdoc.p1;
			p2 = jdoc.p2;
			
			if (p1 && p2)
			{
				instance.rsaPublicKeyModules = p1;
				instance.rsaPublicKeyExpoenent = p2;
				instance.rsa_kinfo = jdoc.p3;
				me.postSecurityKey(is_main);
			}
		}
	},
	
	postSecurityKey: function(is_main) {
		var me = this,
			instance = me.instance,
			formpanel = me.inputpanel,
			opasswd = formpanel.down('[name=oldpasswd]').getValue(),
			npass1 = formpanel.down('[name=newpasswd1]').getValue(),
			npass2 = formpanel.down('[name=newpasswd2]').getValue(),
			enc,
			values = {},
			req;
		
		if (me.getAllValues(values))
			return;
		
		if (npass1 != npass2 && me.option != "2fa")
		{
			IG$.alertmsg(ig$.appname, IRm$.r1("M_PASS_MISMATCH"), null, null, 1, "error");
			return;
		}
		
		enc = IG$.encryptKey(instance, [opasswd, npass1]);
		opasswd = enc[0];
		npass1 = enc[1];
		
		req = new IG$._rpc$();
		req.init(me, 
				{
					ack: "usercontent",
					payload: {address: "/user", keyvar: instance.rsa_kinfo},
					mbody: {option: "changepassword", password: npass1, oldpassword: opasswd}
				}, me, me.rs_processChangePasswd, null, [is_main]);
		req.send();
	},
	
	rs_processChangePasswd: function (jdoc, is_main) {
		var me = this;
		
		if (me.callback)
		{
			me.callback.execute();
		}
		
		if (me.option != "2fa")
		{
			me.close();
		}
		else if (is_main == 1)
		{
			
		}
	},

	set2fa: function(fatype) {
		var me = this,
			req = new IG$._rpc$();

		req.init(me, 
			{
				ack: "usercontent",
				payload: {address: "/user"},
				mbody: {option: "set2fa", fatype: fatype, totp_key: me.totp_key}
			}, me, function(jdoc) {
				if (me.callback)
				{
					me.callback.execute();
				}
				
				me.close();
			}, null);
		req.send();
	},

	draw_qrcode: function() {
		var me = this,
			instance = me.instance,
			dlgLogin = instance.dlgLogin,
			logininfo = dlgLogin.logininfo,
			twofa_option = logininfo.twofa_option,
			twofa_option_map = {},
			qrarea = me.down("[name=qrarea]"),
			qr_div = $(".igc-qrcode", qrarea.el.dom),
			qrcode, i;

		if (twofa_option)
		{
			twofa_option = twofa_option.split(";");

			for (i=0; i < twofa_option.length; i++)
			{
				if (twofa_option[i].indexOf("=") > -1)
				{
					twofa_option_map[twofa_option[i].substring(0, twofa_option[i].indexOf("="))] = twofa_option[i].substring(twofa_option[i].indexOf("=") + 1);
				}
			}

			me.totp_key = "a" + twofa_option_map["totp_key"].substring(0, 10);
		}
		qrcode = new QRCode(qr_div[0], {
			width : 200,
			height : 200
		});

		var ISSUER = encodeURI("AMPLIX"),
			ALGO = "SHA1",
			ACCOUNT_NAME = encodeURI(logininfo.email),
			BASE32_KEY = btoa(me.totp_key);

		while (BASE32_KEY.endsWith("="))
		{
			BASE32_KEY = BASE32_KEY.substring(0, BASE32_KEY.length - 1);
		}

		BASE32_KEY = encodeURI(BASE32_KEY);

		var qrvalue = "otpauth://totp/" + ISSUER + ":" + ACCOUNT_NAME + "?secret=" + BASE32_KEY + "&issuer=" + ISSUER + "&algorithm="  + ALGO + "&digits=6&period=30";
		qrcode.makeCode(qrvalue);
	},
		
	initComponent : function() {
		var me = this,
			instance = me.instance,
			dlgLogin = instance.dlgLogin,
			logininfo = dlgLogin.logininfo,
			twofa_available = logininfo.twofa_available;

		me.title = IRm$.r1('T_PASSWORD_CHANGE');
		
		$s.apply(this, {
			padding: ig$.padding,
			items: [
				{
					html: "<div class='igc-passwd-label'>" + IRm$.r1('L_PWD_LABEL') + "</div>",
					flex: 1,
					border: 0,
					height: 40,
				},
				{
					xtype: "panel",
					name: 'passwordform',
					
					defaultType: 'textfield',
					fieldDefaults: {
						labelWidth: 150,
						anchor: '100%'
					},
					
					layout: "anchor",
					
					items: [
						{
							name: 'oldpasswd',
							fieldLabel: IRm$.r1('L_PWD_OLD'),
							xtype: 'textfield',
							inputType: 'password',
							allowblack: false,
							labelWidth: 150,
							required: true
						},
						{
							xtype: "container",
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									name: 'newpasswd1',
									fieldLabel: IRm$.r1('L_PWD_NEW'),
									xtype: 'textfield',
									inputType: 'password',
									allowblack: false,
									labelWidth: 150,
									flex: 1,
									required: true
								},
								{
									xtype: "button",
									hidden: me.option != "2fa",
									text: IRm$.r1("B_CONFIRM"),
									handler: function() {
										this.processChangePasswd(0);
									},
									scope: this
								}
							]
						},
						{
							name: 'newpasswd2',
							fieldLabel: IRm$.r1('L_PWD_CONFIRM'),
							hidden: me.option == "2fa",
							xtype: 'textfield',
							inputType: 'password',
							allowblack: false,
							labelWidth: 150,
							required: me.option == "2fa" ? false : true
						}
					]
				},
				{
					xtype: "panel",
					layout: "anchor",
					items: [
						{
							xtype: "container",
							height: 50
						},
						{
							html: "<div class='igc-passwd-label'>" + IRm$.r1('L_SEC_2FA') + "</div>",
							flex: 1,
							border: 0,
							height: 40,
						},
						{
							xtype: "panel",
							layout: {
								type: "card",
								animate: {type:"flip", subtype:"vertical"}
							},
							name: "p_2fa",
							items: [
								{
									xtype: "panel",
									layout: {
										type: "hbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "container",
											flex: 1,
										},
										{
											xtype: "container",
											layout: {
												type: "vbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "container",
													width: 20
												},
												{
													xtype: "button",
													text: IRm$.r1("L_TWOFA_EMAIL"),
													hidden: twofa_available && twofa_available.indexOf("email") > -1 ? false : true,
													$w: 200,
													handler: function() {
														var me = this,
															p_2fa = me.down("[name=p_2fa]"),
															p_email = p_2fa.down("[name=p_email]");

														p_2fa.getLayout().setActiveItem(p_email);
													},
													scope: this
												},
												{
													xtype: "container",
													width: 20
												},
												{
													xtype: "button",
													text: IRm$.r1("L_TWOFA_TOTP"),
													hidden: twofa_available && twofa_available.indexOf("totp") > -1 ? false : true,
													$w: 200,
													handler: function() {
														var me = this,
															p_2fa = me.down("[name=p_2fa]"),
															p_totp = p_2fa.down("[name=p_totp]");

														p_2fa.getLayout().setActiveItem(p_totp);
														me.draw_qrcode();
													},
													scope: this
												},
												{
													xtype: "container",
													flex: 1
												}
											]
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								},
								{
									xtype: "panel",
									name: "p_email",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "container",
											flex: 1
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "container",
													flex: 1
												},
												{
													xtype: "button",
													text: IRm$.r1("B_CONFIRM"),
													handler: function() {
														this.set2fa("email")
													},
													scope: this
												},
												{
													xtype: "button",
													text: IRm$.r1("B_CANCEL"),
													handler: function() {
														var me = this,
																p_2fa = me.down("[name=p_2fa]");
	
															p_2fa.getLayout().setActiveItem(0);
													},
													scope: this
												}
											]
										}
									]
								},
								{
									xtype: "panel",
									name: "p_totp",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "container",
											flex: 1
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "container",
													flex: 1
												},
												{
													html: "<div class='igc-qrcode'></div>",
													name: "qrarea",
													width: 200,
													height: 200
												},
												{
													xtype: "container",
													flex: 1
												}
											]
										},
										{
											xtype: "container",
											height: 30
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "container",
													flex: 1
												},
												{
													xtype: "button",
													text: IRm$.r1("B_CONFIRM"),
													handler: function() {
														this.set2fa("totp")
													},
													scope: this
												},
												{
													xtype: "button",
													text: IRm$.r1("B_CANCEL"),
													handler: function() {
														var me = this,
																p_2fa = me.down("[name=p_2fa]");
	
															p_2fa.getLayout().setActiveItem(0);
													},
													scope: this
												}
											]
										},
										{
											xtype: "container",
											flex: 1
										}
									]
								}
							]
						}
					]
				},
				{
					xtype: "container",
					height: 50
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					hidden: me.option == "2fa",
					handler: function() {
						this.processChangePasswd(1);
					},
					scope: this
				}, 
				{
					text: IRm$.r1('B_CLOSE'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					ui.inputpanel = ui.down("[name=passwordform]");
				}
			}
		});
		
		IG$.passwordMgr.superclass.initComponent.apply(this, arguments);
	}
});