	_reqStoryIt: function() {
		var me = this,
			jobid = me.olapset ? me.olapset.jobid : null;
			sheetoption = me.sheetoption,
			smodel = sheetoption ? sheetoption.model : null,
			visual_stories_info = me.visual_stories_info;

		if (jobid && visual_stories_info)
		{
			var pivot = me.reportoption.getCurrentPivot();

			$.each(visual_stories_info, function(i, story) {
				var req = new IG$._rpc$();
				req.init(me, 
					{
						ack: "ai_service",
						payload: {
							option: "story_ai",
							jobid: jobid,
							active: "" + me.sheetindex
						},
						mbody: pivot,
						meta_type: me.meta_type
					}, me, function(jdoc) {
						if (jdoc && jdoc.length)
						{
							var i,
								sinfo,
								cnt,
								n, n1;
							for (i=0; i < jdoc.length; i++)
							{
								sinfo = visual_stories_info[jdoc[i].sequence];

								if (sinfo)
								{
									cnt = jdoc[i].contents.join("\n");
									cnt = cnt.split("\n").join("<br/>\n");
									n = cnt.indexOf("**");
									n1 = cnt.indexOf("**", n + 2);
									while (n > -1 && n1 > n)
									{
										cnt = cnt.substring(0, n) + "<b>" 
											+ cnt.substring(n+2, n1) + "</b>"
											+ cnt.substring(n1 + 2);

										n = cnt.indexOf("**");
										n1 = cnt.indexOf("**", n + 2);
									}

									var scdiv = $(".igc-story-content", sinfo._mdiv);
									scdiv.html(cnt);
								}
							}
						}
					});
				req.send();
			});
		}
	},
	
