	setPageView: function() {
		var me = this,
			pagepanel = me.down("[name=pagepanel]"),
			mdiv = $("#idv-pgview", pagepanel.body.dom),
			result = me.mresults.results[0],
			i, pgcount,
			ntotal,
			sop = me.sheetoption.model,
			rowperpage = sop.rowperpage,
			pagestyle = sop.pagestyle || "p10",
			pgnum, pgstart, pgend, pga,
			pagestart = result.pagestart,
			mul, ppg = 10,
			pgn = [], mdivp,
			mcsv;
			
		mdiv.empty();
		
		if (pagestyle == "p10")
		{
			ppg = 10;
		}
		else if (pagestyle == "p5")
		{
			ppg = 5;
		}
		
		mdivp = $("<div class='idv-pglist'></div>").appendTo(mdiv);
		mul = $("<ul class='idv-pg-tp-" + pagestyle + "'></ul>").appendTo(mdivp);
		
		ntotal = result.rowcnt - result.rowfix;
		pgcount = Math.ceil(ntotal/rowperpage);
		
		if (pgcount > 1 && sop.usepaging == true)
		{
			pagepanel.setVisible(true);
			
			pgstart = Math.floor(pagestart / rowperpage);
			
			mcsv = $("<div class='idv-pg-dwn-csv' title='Download data in CSV'></div>").appendTo(mdiv);
			
			mcsv.bind("click", function() {
				me.downloadAllCSV();
			});
						
			if (pagestyle == "button2")
			{
				if (pgstart > 0)
				{
					var bprev = $("<li class='idv-pg-prev'><span>" + IRm$.r1("B_PG_PREV") + "</span></li>").appendTo(mul);
					bprev.bind("click", function() {
						var n = (pgstart-1) * rowperpage;
						me.goPageView(n);
					});
				}
				
				$("<li class='idv-pg-num idv-pg-num-" + (pgstart+1) + "'><span>" + (pgstart+1) + " / " + pgcount + " pages</span></li>").appendTo(mul);
				
				if (pgstart + 1 < pgcount)
				{
					var bnext = $("<li class='idv-pg-next'><span>" + IRm$.r1("B_PG_NEXT") + "</span></li>").appendTo(mul);
					bnext.bind("click", function() {
						var n = (pgstart + 1) * rowperpage;
						me.goPageView(n);
					});
				}
			}
			else
			{
				pga = Math.floor(pgstart / ppg) * ppg;
				
				pgend = pga + ppg;
				pgend = Math.min(pgcount, pgend);
				
				if (pga > 0)
				{
					var bprev = $("<li class='idv-pg-prev'><span>" + IRm$.r1("B_PG_PREV") + "</span></li>").appendTo(mul);
					bprev.bind("click", function() {
						var n = (pga-1) * rowperpage;
						me.goPageView(n);
					});
				}
				
				for (i=pga; i < pgend; i++)
				{
					pgn.push(i);
				}
				
				$.each(pgn, function(i, npg) {
					var pgnum = (npg+1);
					var btn = $("<li class='" + (npg == pgstart ? "idv-pg-num idv-pg-num-" + pgnum + " active" : "idv-pg-num idv-pg-num-" + pgnum) + "'><span>" + pgnum + "</span></li>").appendTo(mul);
					
					if (npg != pgstart)
					{
						btn.bind("click", function() {
							var n = npg * rowperpage;
							me.goPageView(n);
						});
					}
					
				});
				
				if (pgend < pgcount)
				{
					var bnext = $("<li class='idv-pg-next'><span>" + IRm$.r1("B_PG_NEXT") + "</span></li>").appendTo(mul);
					bnext.bind("click", function() {
						var n = pgend * rowperpage;
						me.goPageView(n);
					});
				}
			}
		}
		else
		{
			pagepanel.setVisible(false);
		}
	},
	
