	updateNoData: function(b_force) {
		var me = this,
			haveresults = b_force ? true : false,
			sheet = me.sheetoption,
			gfilter;
		
		if (!haveresults && me.mresults && me.mresults.results.length > 0 && 
			((me.mresults.results.length == 1 && me.mresults.results[0]._hasNoData == false) || me.mresults.results.length > 1))
		{
			haveresults = true;
		}
		else if (me.mresults && me.mresults._hcell)
		{
			haveresults = true;
		}
		else if (sheet && sheet.mdf && me.mresults && me.mresults.results.length > 0)
		{
			for (var key in sheet.mdf)
			{
				gfilter = sheet.mdf[key];
				if (gfilter && gfilter.op)
				{
					haveresults = true;
					break;
				}
			}
		}
		
		$(".no-result-msg", me.down("[name=noresultpanel]").el.dom).html(IRm$.r1("B_NO_DATA"));
		$(".no-pivot-config", me.down("[name=noresultpanel]").el.dom).hide();
		me.down("[name=mainzone]").setActiveItem(haveresults || me.activeView == 3 ? 0 : 1);
		
		if (!me.updateNoPivot())
			return true;
		
		return !haveresults;
	},
	
