	updateFilterContent: function(finfo) {
	},
	
	getFilterInfo: function(finfo) {
		var me = this,
			fdoc,
			fname,
			fvalue,
			fnode, fsnode,
			flist, fslist,
			i, j, f, fvalue,
			fprop,
			auxfilter = (me.sheetoption) ? me.sheetoption.model.aux_filter : null;
			filter = (me.sheetoption) ? me.sheetoption.model.filter : null;
			
		if (auxfilter)
		{
			for (fname in auxfilter)
			{
				fnode = auxfilter[fname];
				if (fnode)
				{
					me.getSheetFlt(fnode, finfo);
				}
			}
		}
		
		if (filter)
		{
			me.getSheetFlt(filter, finfo);
		}
	},
	
	getSheetFlt: function(filter, finfo) {
		var me = this,
			i, j,
			sfilter,
			condition,
			fname,
			f, fvalue;
		
		if (filter && filter.children && filter.children.length > 0)
		{
			for (i=0; i < filter.children.length; i++)
			{
				condition = filter.children[i];
				if (condition && condition.ftype == "group")
				{
					me.getSheetFlt(condition, finfo);
				}
				else if (condition && condition.ftype == "condition" && condition.fields && condition.fields.length > 0)
				{
					fname = condition.fields[0].name;
					f = finfo[fname] = finfo[fname] || {data: [], p: {}};
					if (condition.values)
					{
						for (j=0; j < condition.values.length; j++)
						{
							fvalue = condition.values[j].value || condition.values[j].code || "";
							if (fvalue && !f.p[fvalue])
							{
								f.data.push(fvalue);
								f.p[fvalue] = 1;
							}
						}
					}
				}
			}
		}
	},
	
