IG$.filterEditorPanel = $s.extend($s.panel, {
	fields: [],
	selvalues: null,
	
	init_f: function() {
		var me = this,
			fitem = me.filteritem,
			fmodel = fitem ? fitem.model : null,
			i,
			rbeditortype = me.down("[name=rbeditortype]"),
			valuetype = me.down("[name=rbvaluetype]"),
			delimiter = me.down("[name=delimiter]"),
			prompttype = me.down("[name=prompttype]"),
			v1, v2, v3,
			
			cnormalvalue = me.down("[name=cnormalvalue]"),
			clongvalue = me.down("[name=clongvalue]"),
			csecondvalue = me.down("[name=csecondvalue]"),
			tval,
			sval;
		
		me.fields = [];
		me.right_fields = [];
		me.formula = "";
		me.useprompt = false;
		me.iscustom = false;
		me.issqlvalue = false;
		me.selvalues = null;
		
		if (fmodel)
		{
			if (me.targetitem)
			{
				fmodel.fields = [me.targetitem];
			}
			
			tval = fmodel.fields;
			
			if (tval && tval.length)
			{
				me.down("[name=itemname]").setValue(tval[0].name);
				for (i=0; i < tval.length; i++)
				{
					me.fields.push(tval[i]);
				}
			}
			
			tval = fmodel.right_fields;
			
			if (tval && tval.length)
			{
				me.down("[name=right_fields1]").setValue(tval[0].name);
				tval.length > 1 && me.down("[name=right_fields2]").setValue(tval[1].name);
				
				for (i=0; i < tval.length; i++)
				{
					me.right_fields.push(tval[i]);
				}
			}
			
			tval = fmodel.values;
			
			if (tval && tval.length > 0)
			{
				me.selvalues = [];
				for (i=0; i < tval.length; i++)
				{
					me.selvalues.push(tval[i]);
				}
			}
			
			me.down("[name=cop]").setValue(fmodel.operator || "EQ");
			me.down("[name=opisnot]").setValue(fmodel.opisnot);
			
			delimiter.setValue(fmodel.delimiter);
			prompttype.setValue(fmodel.promptEditor);
			
			var ctrl = null;
			
			if (fmodel.valuetype == "field")
			{
				valuetype.setValue("field");
			}
			else if (fmodel.useprompt)
			{
				valuetype.setValue("prompt");
			}
			else if (fmodel.issqlvalue)
			{
				valuetype.setValue("sql");
			}
			else
			{
				valuetype.setValue("normal");
			}
			
			rbeditortype.setValue(fmodel.iscustom ? "input" : "list");
			
			me._updLayout();
			
			v1 = cnormalvalue.isVisible();
			v2 = clongvalue.isVisible();
			v3 = csecondvalue.isVisible();
						
			if (v3)
			{
				tval = fmodel.values;
				if (tval && tval.length > 1)
				{
					sval = tval[1].value || tval[1].code;
					sval = IG$._decodeVal(sval);
					me.down("[name=secondvalue]").setValue(sval);
				}
				
				if (tval && tval.length)
				{
					sval = tval[0].value || tval[0].code;
					if (sval.substring(0, 5) == "{enc}")
					{
						sval = Base64.decode(sval.substring(5));
					}
					me.down("[name=" + (v1 ? "normalvalue" : "longvalue") + "]").setValue(sval);
				}
			}
			else
			{
				v1 && me.setFilterDesc(me.down("[name=normalvalue]"));
				v2 && me.setFilterDesc(me.down("[name=longvalue]"));
			}
		}
	},
	
	_confirm: function() {
		var me = this,
			fitem = me.filteritem,
			fmodel = fitem.model,
			editortype = me.down("[name=rbeditortype]").getGroupValue(),
			valuetype = me.down("[name=rbvaluetype]").getGroupValue(),
			delimiter = me.down("[name=delimiter]").getValue(),
			prompttype = me.down("[name=prompttype]").getValue(),
			cnormalvalue = me.down("[name=cnormalvalue]"),
			clongvalue = me.down("[name=clongvalue]"),
			fvalue,
			i;
		
		fmodel.fields = me.fields;
		fmodel.operator = me.down("[name=cop]").getValue();
		fmodel.opisnot = me.down("[name=opisnot]").getValue();
		
		fmodel.valuetype = valuetype;
		fmodel.useprompt = (valuetype == "prompt") ? true : false;
		fmodel.issqlvalue = (valuetype == "sql") ? true : false;
		fmodel.iscustom = true;
		fmodel.delimiter = delimiter || ";";
		fmodel.promptEditor = prompttype;
		fmodel.right_fields = me.right_fields;
		
		if (!fmodel.useprompt && !fmodel.issqlvalue)
		{
			if (editortype == "input")
			{
				if (cnormalvalue.isVisible())
				{
					fvalue = me.down("[name=normalvalue]").getValue();
					fmodel.values = [{code: fvalue, value: fvalue}];
				}
				else if (clongvalue.isVisible())
				{
					fvalue = me.down("[name=longvalue]").getValue();
					if (fitem.operator == 6)
					{
						fvalue = fvalue.split(delimiter);
						fmodel.values = [];
						for (i=0; i < fvalue.length; i++)
						{
							if (fvalue[i] != "")
							{
								fmodel.values.push({code: fvalue[i], value: fvalue[i]});
							}
						}
					}
					else
					{
						fmodel.values = [{code: fvalue, value: fvalue}];
					}
				}
				
				if (fitem.operator == 8)
				{
					var vto = me.down("[name=secondvalue]").getValue();
					fmodel.values.push({code: vto, value: vto});
				}
			}
			else
			{
				fmodel.iscustom = false;
				fmodel.values = me.selvalues;
			}
		}
		else
		{
			fvalue = me.down("[name=longvalue]").getValue();
			if (fmodel.issqlvalue)
			{
				fvalue = IG$._encodeVal(fvalue);
			}
			fmodel.values = [{code: fvalue, value: null}];
		}
	},
	
	_updLayout: function() {
		var me = this,
			editortype = me.down("[name=rbeditortype]").getGroupValue(),
			fieldeditortype = me.down("[name=fieldeditortype]"),
			valuetype = me.down("[name=rbvaluetype]").getGroupValue(),
			op = me.down("[name=cop]").getValue(),
			btnnormalvalue = me.down("[name=btnnormalvalue]"),
			btnlongvalue = me.down("[name=btnlongvalue]"),
			btnsecondvalue = me.down("[name=btnsecondvalue]"),
			delimiter = me.down("[name=delimiter]"),
			normalvalue = me.down("[name=normalvalue]"),
			longvalue = me.down("[name=longvalue]"),
			secondvalue = me.down("[name=secondvalue]"),
			prompttype = me.down("[name=prompttype]"),
			csfield = me.down("[name=csfield]"),
			cs_f2 = me.down("[name=cs_f2]"),
			cnormalvalue = me.down("[name=cnormalvalue]"),
			clongvalue = me.down("[name=clongvalue]"),
			csecondvalue = me.down("[name=csecondvalue]"),
			
			v1=false, v2=false, v3=false;
		
		if (valuetype == "normal") // normal
		{
			fieldeditortype.show();
			prompttype.hide();
			
			switch (op)
			{
			case "EQ": // equal
			case "GTE": // ge
			case "GT": // gt
			case "LTE": // le
			case "LT": // lt
				switch (editortype)
				{
				case "list":
				case "input":
					v1 = true;
					break;
				case "textarea":
					v2 = true;
					break;
				case "fileload":
					v1 = true;
					break;
				}
				break;
			case "IN": // in
			case "NOTIN": // not in
				v2 = true;
				break;
			case "LIKE": // like
				v1 = true;
				break;
			case "BETWEEN": // between
				v1 = true;
				v3 = true;
				break;
			}
			
			if (editortype == "input")
			{
				btnnormalvalue.hide();
				btnlongvalue.hide();
				btnsecondvalue.hide();
				
				normalvalue.setReadOnly(false);
				longvalue.setReadOnly(false);
				secondvalue.setReadOnly(false);
				
				if (v2)
				{
					delimiter.show();
				}
				else
				{
					delimiter.hide();
				}
			}
			else if (editortype == "list")
			{
				btnnormalvalue.show();
				btnlongvalue.show();
				btnsecondvalue.show();
				
				normalvalue.setReadOnly(true);
				longvalue.setReadOnly(true);
				secondvalue.setReadOnly(true);
				
				delimiter.hide();
			}
			csfield.hide();
		}
		else if (valuetype == "field")
		{
			btnnormalvalue.hide();
			btnlongvalue.hide();
			btnsecondvalue.hide();
				
			delimiter.hide();
			fieldeditortype.hide();
			longvalue.setReadOnly(false);
			csfield.show();
			
			cs_f2.setVisible(op == 8);
			prompttype.hide();
		}
		else
		{
			btnnormalvalue.hide();
			btnlongvalue.hide();
			btnsecondvalue.hide();
				
			delimiter.hide();
			fieldeditortype.hide();
			longvalue.setReadOnly(false);
			
			if (valuetype == "prompt")
			{
				prompttype.show();
			}
			else
			{
				prompttype.hide();
			}
			csfield.hide();
			v2 = true;
		}
		
		(v1) ? cnormalvalue.show() : cnormalvalue.hide();
		(v2) ? clongvalue.show() : clongvalue.hide();
		(v3) ? csecondvalue.show() : csecondvalue.hide();
	},
	
	showValueEditor: function(inp) {
		var me = this;
		if (me.fields.length > 0)
		{
			var pop = new IG$.valueSelectWindow({
				instance: me.instance,
				field: me.fields[0],
				meta_type: me.meta_type,
				reportoption: me.reportoption,
				callback: new IG$.callBackObj(this, function(sel, inp) {
					var me = this,
						ctrl = me.down("[name=" + inp + "]");
					
					if (sel && sel.length > 0)
					{
						me.selvalues = sel;
					}
					
					me.setFilterDesc(ctrl);
				}, inp)
			});
			IG$.checkLogin(this, pop);
		}
	},
	
	setFilterDesc: function(ctrl) {
		var me = this,
			fitem = me.filteritem,
			r = fitem.getValueDesc(me.selvalues);
			
		ctrl.setValue(r);
	},
	
	selectItem: function(sname, sobj, secondvalue) {
		var me = this,
			cubeuid,
			rop = me.reportoption;
			
		cubeuid = me.cubeuid || (rop && rop.datasource ? rop.datasource.uid : "");
		
		var dlgitemsel = new IG$.metaSelectDlg({
			instance: me.instance,
			visibleItems: "folder;metric;measure;formulameasure;custommetric",
			tree_options: {
				cubebrowse: true,
				rootuid: cubeuid
			},
			callback: new IG$.callBackObj(me, function(item) {
				var me = this;
					
				if (secondvalue)
				{
					me[(sobj || sname)] = me[(sobj || sname)] || [];
					me[(sobj || sname)].push(item);
				}
				else
				{
					me[(sobj || sname)] = [item];
				}
				me.down("[name=" + sname + "]").setValue(item.name);
			})
		});
		
		IG$.checkLogin(this, dlgitemsel);
	},
	
	initComponent: function() {
		var operatordp = [],
			me = this;
			
		me.addEvents("add_filter");
			
		$.each(IG$.filteropcodes, function(key, value) {
			operatordp.push({field: key, label: value.locale});
		});
		
		$s.apply(this, {
			layout: {
				type: (me._cmode == 1 ? "hbox" : "vbox"),
				align: "stretch"
			},
			
			fieldDefaults: {
				labelWidth: 150,
				anchor: "100%"
			},
			
			items: [
				{
					xtype: "fieldset",
					defaultType: "textfield",
					layout: "anchor",
					defaults: {
						anchor: "100%",
						labelAlign: me._cmode == 1 ? "top" : "left"
					},

					items: [
						{
							xtype: "fieldcontainer",
							fieldLabel: IRm$.r1("L_ITEM"),
							layout: "hbox",
							items: [
								{
									name: "itemname",
									xtype: "textfield",
									allowBlank: false,
									readOnly: true,
									emptyText: IRm$.r1("M_SEL_ITEM"),
									flex: 1
								},
								{
									xtype: "button",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									width: 20,
									handler: function() {
										this.selectItem("itemname", "fields");
									},
									scope: this
								}
							]
						},
						{
							xtype: "fieldcontainer",
							layout: "hbox",
							items: [
								{
									fieldLabel: IRm$.r1("B_OP"),
									name: "cop",
									xtype: "combobox",
									queryMode: "local",
									valueField: "field",
									displayField: "label",
									editable: false,
									store: {
										fields: [
											"field", "label"
										],
										data: operatordp
									},
									listeners: {
										select: function() {
											this._updLayout();
										},
										scope: this
									}
								},
								{
									xtype: "checkbox",
									name: "opisnot",
									boxLabel: IRm$.r1("L_OP_NOT"),
									listeners: {
										change: function(tobj) {
											var me = this,
												cop = me.down("[name=cop]"),
												isnot = tobj.getValue(),
												rec,
												i, k,
												dmap = {},
												opcodes = IG$.filteropcodes,
												copval = cop.getValue();
											
											$.each(opcodes, function(k, val) {
												dmap[k] = val.lcode;
											});
											
											for (i=0; i < cop.store.data.items.length; i++)
											{
												rec = cop.store.data.items[i];
												rec.set("label", IRm$.r1(dmap[rec.get("field")] + (isnot ? "_NOT" : "")));
											}
											
											cop.setValue(copval);
										},
										scope: this
									}
								}
							]
						},
						{
							name: "valuetype",
							xtype: "radiogroup",
							fieldLabel: IRm$.r1("L_VALUE_TYPE"),
							vertical: false,
							defaults: {
								width: 70
							},
							items: [
								{
									boxLabel: IRm$.r1("B_NORMAL"), // "Normal", 
									name: "rbvaluetype", inputValue: "normal", checked: true
								},
								{
									boxLabel: IRm$.r1("B_SQL"), // "SQL", 
									name: "rbvaluetype", inputValue: "sql"
								},
								{
									boxLabel: IRm$.r1("B_FIELD"), // "Column",
									name: "rbvaluetype", inputValue: "field"
								},
								{
									boxLabel: IRm$.r1("B_PROMPT"), // "Prompt", 
									hidden: true,
									name: "rbvaluetype", inputValue: "prompt"
								}
							],
							listeners: {
								change: function(field, newvalue, oldvalue, eOpts) {
									this._updLayout();
								},
								scope: this
							}
						}
					]
				},
				{
					xtype: "panel",
					layout: "anchor",
					border: 0,
					autoScroll: true,
					padding: 0,
					defaults: {
						labelAlign: me._cmode == 1 ? "top" : "left"
					},
					dockedItems: [
						me._cmode == 1 ? {
							dock: "bottom",
							xtype: "toolbar",
							items: [
								"->",
								{
									xtype: "button",
									text: IRm$.r1("B_ADD"),
									handler: function() {
										this.fireEvent("add_filter", this);
									},
									scope: this
								}
							]
						} : null
					],
					items: [
						{
							fieldLabel: IRm$.r1("L_EDITOR_TYPE"),
							xtype: "fieldcontainer",
							layout: "anchor",
							name: "fieldeditortype",
							defaults: {
								flex: 1,
								anchor: "100%",
								hideLabel: true
							},
							items: [
								{
									name: "editortype",
									xtype: "radiogroup",
									vertical: false,
									plain: true,
									items: [
										{
											boxLabel: IRm$.r1("L_E_VALUE"), 
											name: "rbeditortype", inputValue: "input", checked: true
										},
										{
											boxLabel: IRm$.r1("L_E_LIST"), 
											name: "rbeditortype", inputValue: "list"
										}
									],
									listeners: {
										change: function () {
											this._updLayout();
										},
										scope: this
									}
								}
							]
						},
						{
							fieldLabel: IRm$.r1("L_VAL_DELIM"),
							xtype: "textfield",
							name: "delimiter",
							width: 120
						},
						{
							fieldLabel: IRm$.r1("L_PROMPT_TYPE"),
							name: "prompttype",
							xtype: "combobox",
							queryMode: "local",
							valueField: "field",
							displayField: "label",
							editable: false,
							hidden: true,
							store: {
								fields: [
									"field", "label"
								],
								data: [
									{field: 1, label: "Text input"},
									{field: 2, label: "Combobox"},
									{field: 3, label: "Date field"},
									{field: 4, label: "Select window"}
								]
							},
							listeners: {
								select: function() {
									this._updLayout();
								},
								scope: this
							}
						},
						{
							xtype: "fieldcontainer",
							name: "cnormalvalue",
							fieldLabel: IRm$.r1("L_F_VALUE"),
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									name: "normalvalue",
									flex: 1,
									emptyText: IRm$.r1("M_SEL_ITEM"),
									xtype: "textfield"
								},
								{
									xtype: "button",
									name: "btnnormalvalue",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									width: 20,
									handler: function() {
										this.showValueEditor("normalvalue");
									},
									scope: this
								}
							]
						},
						
						{
							xtype: "fieldcontainer",
							name: "clongvalue",
							fieldLabel: IRm$.r1("L_F_VALUE_LNG"),
							layout: {
								type: "hbox",
								align: "stretch"
							},
							hidden: true,
							items: [
								{
									name: "longvalue",
									flex: 1,
									height: 120,
									xtype: "textarea"
								},
								{
									xtype: "button",
									name: "btnlongvalue",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									width: 20,
									handler: function() {
										this.showValueEditor("longvalue");
									},
									scope: this
								}
							]
						},
						
						{
							xtype: "fieldcontainer",
							name: "csecondvalue",
							fieldLabel: IRm$.r1("L_F_VALUE_TO"),
							layout: {
								type: "hbox",
								align: "stretch"
							},
							hidden: true,
							items: [
								{
									name: "secondvalue",
									flex: 1,
									xtype: "textfield"
								},
								{
									xtype: "button",
									name: "btnsecondvalue",
									iconCls: "icon-toolbar-search",
									tooltip: IRm$.r1("B_SEARCH"),
									width: 20,
									handler: function() {
										this.showValueEditor("secondvalue");
									},
									scope: this
								}
							]
						},
						{
							xtype: "fieldcontainer",
							name: "csfield",
							hidden: true,
							layout: "vbox",
							items: [
								{
									xtype: "fieldcontainer",
									name: "cs_f1",
									fieldLabel: IRm$.r1("L_ITEM"),
									layout: "hbox",
									items: [
										{
											name: "right_fields1",
											xtype: "textfield",
											allowBlank: false,
											readOnly: true,
											emptyText: IRm$.r1("M_SEL_ITEM"),
											flex: 1
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											width: 20,
											handler: function() {
												this.selectItem("right_fields1", "right_fields");
											},
											scope: this
										}
									]
								},
								{
									xtype: "fieldcontainer",
									name: "cs_f2",
									fieldLabel: IRm$.r1("L_ITEM"),
									layout: "hbox",
									items: [
										{
											name: "right_fields2",
											xtype: "textfield",
											allowBlank: false,
											readOnly: true,
											emptyText: IRm$.r1("M_SEL_ITEM"),
											flex: 1
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											width: 20,
											handler: function() {
												this.selectItem("right_fields2", "right_fields", 1);
											},
											scope: this
										}
									]
								},
							]
						}
					]
				}
			]
		});
		IG$.filterEditorPanel.superclass.initComponent.apply(this, arguments);
	}
});


	
IG$.filterEditor = $s.extend($s.window, {
	
	modal: true,
	region:"center",
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 500,
	height: 450,
	
	reportoption: null,
	
	callback: null,
		
	init_f: function() {
		var me = this,
			mainpanel = me.mainpanel;
		mainpanel.init_f();
	},
	
	_confirm: function() {
		var me = this,
			mainpanel = me.mainpanel;
			
		mainpanel._confirm();
		
		me.callback && me.callback.execute();
		
		me.close();
	},
	
	initComponent : function() {
		var me = this;
		
		me.title = IRm$.r1("T_FILTER");
				 
		$s.apply(this, {
			defaults:{
				padding: ig$.padding
			},
			
			layout: "fit",
			
			items: [
				new IG$.filterEditorPanel({
					instance: me.instance,
					filteritem: me.filteritem,
					meta_type: me.meta_type,
					name: "mainp",
					padding: ig$.padding,
					targetitem: me.targetitem,
					cubeuid: me.cubeuid,
					reportoption: me.reportoption
				})
			],
			buttons:[
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, {
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					var panel = this;
					
					me.mainpanel = panel.down("[name=mainp]");
					
					setTimeout(function() {
						panel.init_f();
					}, 300);
				}
			}
		});
		
		IG$.filterEditor.superclass.initComponent.apply(this, arguments);
	}
});