IG$.__analoption = IG$.__analoption || {
	analcateg: [
		{name: "All", value: "all"},
		{name: "Descriptive Statistics", value: "descriptive"},
		{name: "Compare Means", value: "compare"},
		{name: "Regression", value: "regression"},
		{name: "Process", value: "process"}
	],
	analtype: [
		{label:"Descriptive Statistics", type:"descriptive", img: "column", grp: "descriptive", opt: {popt_g1: 1, popt_output: 1}},
		{label:"Frequencies", type:"frequencies", img: "column", grp: "descriptive", opt: {popt_g1: 1, popt_output: 1}},
		{label:"Means", type:"means", img: "column", grp: "compare", opt: {popt_g1: 1, popt_output: 1}},
		{label:"One-Sample T Test", type:"onesamplettest", img: "column", grp: "compare", opt: {popt_g1: 1, popt_output: 1}},
		{label:"Independent Samples T Test", type:"independent_ttest", img: "column", grp: "compare", opt: {popt_g1: 1, popt_output: 1}},
		{label:"Paired_Samples T Test", type:"paired_tt", img: "column", grp: "compare", opt: {popt_g1: 1, popt_output: 1}},
		{label:"One-Way ANOVA", type:"anova", img: "column", grp: "compare", opt: {popt_g1: 1, popt_output: 1}},
		{label:"Linear", type:"linear", img: "column", grp: "regression", opt: {popt_g1: 0, popt_output: 1, popt_g2: 1}},
		{label:"Process Capability Indexes", type: "proc_cap_index", img: "column", grp: "process", opt: {popt_g1: 1, popt_output: 1}}
	]
};

IG$.analeditor = $s.extend($s.window, {
	modal: true,
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 400,
	height: 500,
	
	_init: function() {
		var me = this,
			g_list = me.down("[name=g_list]"),
			model = me.sheetoption.model,
			opt;
		
		opt = model.anal_options = model.anal_options || [];
		$.each(opt, function(i, o) {
			o.selected = true;
		});
		g_list.store.loadData(opt);
	},
	
	editItem: function(rec) {
		var me = this,
			dlg = new IG$.analwizard({
				instance: me.instance,
				sheetoption: me.sheetoption,
				_eobj: rec.data,
				callback: new IG$.callBackObj(me, function() {
					
				})
			});
			
		IG$.showDlg(me, dlg);
	},
	
	_confirm: function() {
		var me = this,
			sheetoption = me.sheetoption.model,
			items = [],
			g_list = me.down("[name=g_list]"),
			i, rec;
			
		for (i=0; i < g_list.store.data.items.length; i++)
		{
			rec = g_list.store.data.items[i];
			items.push(rec.data);
		}
		
		sheetoption.anal_options = items;
		
		me.callback && me.callback.execute(me);
		me.close();
	},
	
	initComponent : function() {
		var me = this;
			
		me.title = IRm$.r1("T_ANAL_WIZARD");
		
		$s.apply(me, {
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					padding: ig$.padding,
					items: [
						{
							xtype: "gridpanel",
							name: "g_list",
							store: {},
							flex: 1,
							selType: "checkboxmodel",
							selModel: {
								mode: "MULTI"
							},
							columns: [
								{
									text: IRm$.r1("B_NAME"),
									flex: 1,
									dataIndex: "name",
									tdCls: "igc-td-link",
								},
								{
									text: IRm$.r1("B_DESC"),
									flex: 1,
									dataIndex: "description"
								},
								{
									xtype: "actioncolumn",
									width: 60,
									items: [
										{
											iconCls: "icon-grid-config",
											tooltip: "Config item",
											handler: function (grid, rowIndex, colIndex) {
												var me = this,
													rec = grid.store.getAt(rowIndex);
													
												me.editItem(rec);
											},
											scope: this
										},
										{
											iconCls: "icon-grid-delete",
											tooltip: "Delete Item",
											handler: function (grid, rowIndex, colIndex) {
												var me = this,
													rec = grid.store.getAt(rowIndex);
													
												grid.store.remove(rec);
											},
											scope: this
										}
									]
								}
							],
							listeners: {
								cellclick: function(view, node, c, rec, rindex, e) {
									var me = this;
									if (c == 1)
									{
										me.editItem(rec);
									}
								},
								scope: this
							},
							tbar: [
								{
									text: IRm$.r1("L_NEW_ANAL"), // "New Analysis",
									handler: function() {
										var me = this,
											ditem = {},
											pop = new IG$.analwizard({
												instance: me.instance,
												reportoption: me.reportoption, 
												sheetoption: me.sheetoption,
												_eobj: ditem,
												callback: new IG$.callBackObj(me, function(dlg) {
													var g_list = me.down("[name=g_list]");
													g_list.store.add(ditem);
												})
											});
										IG$.checkLogin(this, pop);
									},
									scope: this
								},
								{
									text: IRm$.r1("L_DELETE_CHECKED"), // "Delete Selected",
									handler: function() {
									},
									scope: this
								}
							]
						}
					]
				}
			],
			buttons:[
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					var me = this;
						
					me._init();
				}
			}
		});
		
		IG$.analeditor.superclass.initComponent.apply(this, arguments);
	}
});

IG$.analwizard = $s.extend($s.window, {
	modal: true,
	layout: "fit",
	
	closable: false,
	resizable:false,
	width: 550,
	height: 480,
	
	opt_panels: [
		{
			name: "popt_output",
			condition: null
		},
		{
			name: "popt_g1",
			condition: null
		},
		{
			name: "popt_g2",
			condition: null
		}
	],
	
	_init: function() {
		var me = this,
			model = me.sheetoption.model,
			opt = model.anal_options,
			analtypeview = me.down("[name=_b]"),
			g_inp1 = me.down("[name=g_inp1]"),
			g_out1 = me.down("[name=g_out1]"),
			record,
			drows = [],
			dtimerows = [],
			dmeasures = [],
			dmeasures2 = [],
			ritem, i;
			
		for (i=0; i < model.rows.length; i++)
		{
			dmeasures.push(IG$.CloneObject(model.rows[i]));
			dmeasures2.push(IG$.CloneObject(model.rows[i]));
		}
		
		for (i=0; i < model.measures.length; i++)
		{
			dmeasures.push(IG$.CloneObject(model.measures[i]));
			dmeasures2.push(IG$.CloneObject(model.measures[i]));
		}
		
		g_inp1.store.loadData(dmeasures);
		g_out1.store.loadData(dmeasures2);
		
		me._einit();
	},
	
	_einit: function() {
		var me = this,
			analtypeview = me.down("[name=_b]"),
			g_inp1 = me.down("[name=g_inp1]"),
			g_out1 = me.down("[name=g_out1]"),
			g_inp1_smodel = g_inp1.getSelectionModel(),
			g_out1_smodel = g_out1.getSelectionModel(),
			eobj = me._eobj,
			i, record,
			imap = {},
			bgrp;
		
		$.each(IG$.__analoption.analtype, function(i, a) {
			if (a.type == eobj.analtype)
			{
				bgrp = a.grp;
				return false;
			}
		});
		
		me.down("[name=analgroup]").setValue(bgrp || "");
		analtypeview.setValue(eobj.analtype);
		g_inp1_smodel.clear();
		g_out1_smodel.clear();
		
		if (eobj.input_fields)
		{
			for (i=0; i < eobj.input_fields.length; i++)
			{
				imap[eobj.input_fields[i]] = 1;
			}
			
			for (i=0; i < g_inp1.store.data.items.length; i++)
			{
				record = g_inp1.store.data.items[i];
				if (imap[record.get("uid")])
				{
					g_inp1_smodel.select(record, true);
				}
			}
		}
		
		eobj.options = eobj.options || {};
		
		me.down("[name=p_general]").setAllValues(eobj, 1);
		
		if (eobj.regression_fields)
		{
			var regression_fields = eobj.regression_fields;
			
			imap = {};
			
			for (i=0; i < regression_fields.length; i++)
			{
				imap[regression_fields[i]] = 1;
			}
			
			for (i=0; i < g_out1.store.data.items.length; i++)
			{
				record = g_out1.store.data.items[i];
				if (imap[record.get("uid")])
				{
					g_out1_smodel.select(record, true);
				}
			}
		}
		
		$.each(me.opt_panels, function(i, dobj) {
			var f = me.down("[name=" + dobj.name + "]");
			f.setAllValues(eobj.options, 1);
		});
		
		me._elayout();
	},
	
	_elayout: function() {
		var me = this,
			eobj = me._eobj,
			analtype = eobj ? eobj.analtype : null,
			seltype;
		
		if (analtype)
		{
			seltype = me._get_tp(analtype);
			
			$.each(me.opt_panels, function(i, dobj) {
				var p = me.down("[name=" + dobj.name + "]");
				
				if (seltype && seltype.opt && seltype.opt[dobj.name])
				{
					p.show();
				}
				else
				{
					p.hide();
				}
			});
		}
	},
	
	_get_tp: function(analtype) {
		var r = null;
		
		$.each(IG$.__analoption.analtype, function(i, tp) {
			if (tp.type == analtype)
			{
				r = tp;
				return false;
			}
		});
		
		return r;
	},
	
	_econfirm: function() {
		var me = this,
			eobj = me._eobj,
			g_inp1 = me.down("[name=g_inp1]"),
			g_out1 = me.down("[name=g_out1]"),
			sel, i,
			sel_out,
			r = 1;
		
		if (eobj)
		{
			sel = g_inp1.getSelectionModel().selected;
			sel_out = g_out1.getSelectionModel().selected;
			
			eobj.input_fields = [];
			eobj.options = eobj.options || {};
			
			eobj.regression_fields = [];
			
			if (sel)
			{
				for (i=0; i < sel.length; i++)
				{
					eobj.input_fields.push(sel.items[i].get("uid"));
				}
			}
			
			if (sel_out)
			{
				for (i=0; i < sel_out.length; i++)
				{
					eobj.regression_fields.push(sel_out.items[i].get("uid"));
				}
			}
			
			var err = me.down("[name=p_general]").getAllValues(eobj, 1);
			
			if (err)
			{
				r = 0;
			}
			else
			{
				$.each(me.opt_panels, function(i, dobj) {
					var f = me.down("[name=" + dobj.name + "]"),
						berr;
					berr = f.getAllValues(eobj.options, 1);
					
					if (berr)
					{
						r = 0;
						return false;
					}
				});
			}
		}
		
		return r;
	},
	
	_confirm: function() {
		var me = this;
		
		if (!me._econfirm())
			return;
		
		me.callback && me.callback.execute();
		
		me.close();
	},
	
	_changeGroup: function() {
		var me = this,
			analgroup = me.down("[name=analgroup]"),
			analtypelist = me.analtypelist,
			analtypeview = me.down("[name=_b]"),
			analtype = analgroup.getValue(),
			analitem,
			opt = me.sheetoption.model.anal_options,
			atype = analtypeview.getValue() || opt.analtype,
			dp = [], i,
			record;
			
		if (analtype != me.analtype)
		{
			for (i=0; i < analtypelist.length; i++)
			{
				analitem = analtypelist[i];
				if (analtype == "all" || analitem.grp == analtype || atype == analitem.type)
				{
					dp.push(analitem);
				}
			}
			
			analtypeview.store.loadData(dp);
			
			for (i=0; i < analtypeview.store.data.items.length; i++)
			{
				record = analtypeview.store.data.items[i];
				if (record.data.type == atype)
				{
					setTimeout(function() {
						analtypeview.setValue(record.data.type);
					}, 100);
					break;
				}
			}
			
			me.analtype = analtype;
		}
	},
	
	
	initComponent : function() {
		var me = this,
			analtype = IG$.__analoption.analtype;
			
		me.title = IRm$.r1("T_ANAL_WIZARD");
		me.analtypelist = analtype;
		me._custPnls = [];
		
		$s.apply(me, {
			items: [
				{
					xtype: "panel",
					layout: {
						type: "vbox",
						align: "stretch"
					},
					autoScroll: true,
					border: 0,
					padding: ig$.padding,
					items: [
						{
							xtype: "fieldset",
							title: "General",
							name: "p_general",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									fieldLabel: IRm$.r1("B_NAME"),
									name: "t_name",
									mapname: "name",
									required: true
								},
								{
									xtype: "textarea",
									fieldLabel: IRm$.r1("B_DESC"),
									mapname: "description",
									name: "t_desc",
									height: 120
								},
								{
									xtype: "combobox",
									name: "analgroup",
									fieldLabel: IRm$.r1("L_ANAL_GROUP"),
									queryMode: "local",
									displayField: "name",
									valueField: "value",
									editable: false,
									autoSelect: true,
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: IG$.__analoption.analcateg
									},
									listeners: {
										change: function(field, newvalue, oldvalue, opt) {
											var me = this;
											me._changeGroup();
										},
										scope: this
									}
								},
								{
									xtype: "combobox",
									name: "_b",
									fieldLabel: IRm$.r1("L_ANALYSIS_TYPE"), // "Analysis Type",
									queryMode: "local",
									valueField: "type",
									displayField: "label",
									mapname: "analtype",
									store: {
										xtype: "store",
										fields: ["type", "label"]
									},
									listeners: {
										change: function(field, newvalue, oldvalue, opt) {
											var me = this,
												model = me.sheetoption.model,
												opt = model.anal_options,
												analtype = newvalue;
											
											me._eobj.analtype = analtype;
											me._elayout();
										},
										scope: this
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_ASTEP_1"),
							name: "popt_output",
							border: 0,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldset",
									title: "Input",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "gridpanel",
											height: 200,
											name: "g_inp1",
											selType: "checkboxmodel",
											selModel: {
												checkSelector: ".x-grid-cell"
											},
											store: {
											},
											columns: [
												{
													text: IRm$.r1("B_NAME"),
													flex: 1,
													dataIndex: "name"
												}
											]
										}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_ASTEP_2"),
							name: "popt_g1",
							border: 0,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldset",
									title: "Output options",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "checkbox",
											boxLabel: "Summary statistics",
											name: "s_stat"
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "checkbox",
													boxLabel: "Confidence Level for Mean",
													name: "s_conf_level_mean"
												},
												{
													xtype: "numberfield",
													name: "s_conf_level_mean_val"
												}
											]
										},
										{
											xtype: "container",
											layout: {
												type: "hbox",
												align: "stretch"
											},
											items: [
												{
													xtype: "checkbox",
													boxLabel: "Kth Largest / Smallest",
													name: "s_kth_ls"
												},
												{
													xtype: "numberfield",
													name: "s_kth_ls_val"
												}
											]
										}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_ASTEP_2"),
							name: "popt_g2",
							border: 0,
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "fieldset",
									title: "Output",
									layout: {
										type: "vbox",
										align: "stretch"
									},
									items: [
										{
											xtype: "gridpanel",
											height: 200,
											name: "g_out1",
											selType: "checkboxmodel",
											selModel: {
												checkSelector: ".x-grid-cell"
											},
											store: {
											},
											columns: [
												{
													text: IRm$.r1("B_NAME"),
													flex: 1,
													dataIndex: "name"
												}
											]
										}
									]
								}
							]
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					var me = this;
						
					me._init();
				}
			}
		});
		
		IG$.analwizard.superclass.initComponent.apply(this, arguments);
	}
});